<?php
require __DIR__ . '/../app/bootstrap.php';
require __DIR__ . '/../app/order_manual.php';
$u=require_role(['owner','admin','manager','staff']);$msg=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();skynoc_manual_order($db,(int)($_POST['order_id']??0),(string)($_POST['license_key']??''),(int)$u['id']);$msg='Order completed and key assigned.';}catch(Throwable $e){$error=$e->getMessage();}}
$orders=$db->query("SELECT o.*,p.name package_name,r.name reseller_name,r.email reseller_email FROM orders o JOIN packages p ON p.id=o.package_id JOIN resellers r ON r.id=o.reseller_id WHERE o.status IN ('pending','processing') ORDER BY o.id ASC LIMIT 100")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pending Orders — SkyNoc</title><link rel="stylesheet" href="/admin-page-ui.css"><style>.wrap{max-width:1100px;margin:25px auto;padding:0 16px}.hero,.card{background:#fff;border:1px solid #e4e7ec;border-radius:18px;padding:20px;margin-bottom:14px}.hero{background:linear-gradient(135deg,#111827,#1d4ed8);color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.meta{font-size:12px;color:#667085;line-height:1.8}.btn{border:0;border-radius:10px;padding:10px 14px;font-weight:800;background:#465fff;color:#fff}.alert{padding:12px;border-radius:12px;margin-bottom:14px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:700px){.grid{grid-template-columns:1fr}}</style></head><body><div class="top"><strong>SkyNoc / Admin</strong><span><?=e($u['name'])?> · <a href="/admin">Dashboard</a></span></div><div class="wrap"><div class="hero"><h1>Pending Order Fulfillment</h1><p>Enter the provider key when inventory is empty.</p></div><?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="alert err"><?=e($error)?></div><?php endif;?><?php if(!$orders):?><div class="card">No pending orders.</div><?php endif;?><?php foreach($orders as $o):?><div class="card"><div class="grid"><div><strong>#<?=e((string)$o['id'])?> — <?=e($o['package_name'])?></strong><div class="meta">Reseller: <?=e($o['reseller_name'])?> (<?=e($o['reseller_email'])?>)<br>Domain: <?=e($o['domain'])?><br>Status: <?=e(strtoupper($o['status']))?> · Amount: $<?=e(number_format((float)$o['amount'],2))?></div></div><form method="post"><?=csrf_field()?><input type="hidden" name="order_id" value="<?=e((string)$o['id'])?>"><label>Provider License Key</label><input required name="license_key" placeholder="Enter license key"><br><br><button class="btn">Assign & Complete</button></form></div></div><?php endforeach;?></div></body></html>
